import React from "react";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
    label?: string;
    error?: string;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
    ({ className = "", label, error, ...props }, ref) => {
        return (
            <div className="space-y-2 w-full">
                {label && (
                    <label className="text-sm font-medium text-gray-400 ml-1 block">
                        {label}
                    </label>
                )}
                <input
                    ref={ref}
                    className={`w-full bg-[var(--color-dark-bg)] border rounded-lg px-4 py-3 text-white focus:outline-none transition-all
            ${error
                            ? "border-red-500 focus:ring-1 focus:ring-red-500 focus:border-red-500"
                            : "border-[var(--color-dark-border)] focus:border-[var(--color-primary-gold)] focus:ring-1 focus:ring-[var(--color-primary-gold)]"
                        }
            ${className}`}
                    {...props}
                />
                {error && (
                    <p className="text-sm text-red-500 ml-1">{error}</p>
                )}
            </div>
        );
    }
);
Input.displayName = "Input";
