"use client";

import { useState } from "react";
import { Scissors } from "lucide-react";
import { Button } from "../components/ui/Button";
import { Input } from "../components/ui/Input";
import { useRouter } from "next/navigation";

// Simple validation helpers
const emailRegex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/;
const phoneRegex = /^\+?\d{10,15}$/;

export default function LoginPage() {
  const router = useRouter();
  const [isRegistering, setIsRegistering] = useState(false);
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [profilePhoto, setProfilePhoto] = useState<File | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (isRegistering) {
      // Basic validation for registration
      if (!name || !phone || !email || !password || !confirmPassword) {
        setError("Preencha todos os campos obrigatórios.");
        return;
      }
      if (!emailRegex.test(email)) {
        setError("E-mail inválido.");
        return;
      }
      if (!phoneRegex.test(phone)) {
        setError("Telefone inválido. Use apenas números e, opcionalmente, o +.");
        return;
      }
      if (password !== confirmPassword) {
        setError("As senhas não coincidem.");
        return;
      }
    } else {
      // Basic validation for login
      if (!email || !password) {
        setError("Preencha e-mail e senha.");
        return;
      }
    }

    setIsLoading(true);
    // Simulate async request
    setTimeout(() => {
      setIsLoading(false);
      if (isRegistering) {
        // Mock registration success -> auto login as client
        router.push("/client");
        return;
      }
      // Mock login logic
      if (password !== "123456") {
        setError("Senha incorreta. A senha é: 123456");
        return;
      }
      if (email === "admin@teste.com") {
        router.push("/admin");
      } else if (email === "barbeiro@teste.com") {
        router.push("/barber");
      } else if (email === "cliente@teste.com") {
        router.push("/client");
      } else {
        setError("Tente: admin@teste.com, barbeiro@teste.com ou cliente@teste.com");
      }
    }, 1000);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setProfilePhoto(e.target.files[0]);
    }
  };

  return (
    <div className="min-h-screen bg-[var(--color-dark-bg)] text-white flex flex-col items-center justify-center p-4 selection:bg-[var(--color-primary-gold)] selection:text-black">
      {/* Decorative blurred elements */}
      <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-[var(--color-primary-gold)]/10 rounded-full blur-[120px] pointer-events-none" />
      <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-[var(--color-primary-gold)]/10 rounded-full blur-[120px] pointer-events-none" />

      <div className="w-full max-w-md bg-[var(--color-dark-card)] rounded-2xl p-8 shadow-2xl border border-[var(--color-dark-border)] relative z-10 animate-fade-in-up">
        {/* Header */}
        <div className="flex flex-col items-center mb-8">
          <div className="w-16 h-16 bg-[var(--color-dark-bg)] border border-[var(--color-primary-gold)] rounded-full flex items-center justify-center mb-4 shadow-[0_0_15px_rgba(212,175,55,0.2)]">
            <Scissors className="w-8 h-8 text-[var(--color-primary-gold)]" strokeWidth={1.5} />
          </div>
          <h1 className="text-3xl font-light tracking-wider text-white italic uppercase">Marciel</h1>
          <p className="text-[var(--color-primary-gold)] tracking-[0.3em] text-sm mt-1 uppercase font-semibold">BarberShop</p>
        </div>

        {/* Switch between login/register */}
        <div className="flex gap-4 mb-8 border-b border-[var(--color-dark-border)]">
          <button type="button" onClick={() => setIsRegistering(false)} className={`pb-2 px-2 text-sm font-medium transition-colors relative ${!isRegistering ? 'text-[var(--color-primary-gold)]' : 'text-gray-500 hover:text-gray-300'}`}>ENTRAR</button>
          <button type="button" onClick={() => setIsRegistering(true)} className={`pb-2 px-2 text-sm font-medium transition-colors relative ${isRegistering ? 'text-[var(--color-primary-gold)]' : 'text-gray-500 hover:text-gray-300'}`}>CRIAR CONTA</button>
        </div>

        {/* Form */}
        <form onSubmit={handleLogin} className="space-y-5">
          {error && (
            <div className="bg-red-500/10 border border-red-500/50 text-red-400 text-sm px-4 py-3 rounded-lg animate-fade-in-up">{error}</div>
          )}

          {isRegistering && (
            <>
              <Input label="Nome Completo" type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Seu nome" required />
              <Input label="Telefone" type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+55 11 99999-9999" required />
              <Input label="Foto de Perfil (opcional)" type="file" onChange={handlePhotoChange} />
            </>
          )}

          <Input label="E-mail / Usuário" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Digite seu email" required />

          <div className="space-y-2">
            <div className="flex justify-between items-center ml-1">
              <label className="text-sm font-medium text-gray-400 block">Senha</label>
              {!isRegistering && (
                <a href="#" className="text-xs text-[var(--color-primary-gold)] hover:text-[var(--color-primary-gold-hover)] transition-colors">Esqueceu a senha?</a>
              )}
            </div>
            <Input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Digite sua senha" required />
          </div>

          {isRegistering && (
            <Input label="Confirmar Senha" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Confirme sua senha" required />
          )}

          <Button type="submit" className="w-full mt-4" size="lg" isLoading={isLoading}>
            {isRegistering ? 'CRIAR CONTA' : 'ACESSAR AGORA'}
          </Button>
        </form>
      </div>

      <p className="mt-8 text-xs text-gray-500 tracking-wider relative z-10">&copy; {new Date().getFullYear()} MARCIEL BARBERSHOP. TODOS OS DIREITOS RESERVADOS.</p>
    </div>
  );
}
